// The public half of Kinsay's update key (desktop/make-update-key.mjs): an update must be signed
// with its private half, which only Damian's PC holds.
namespace TranslateApp
{
    static class UpdateKey
    {
        public const string Public = "<RSAKeyValue><Modulus></Modulus><Exponent>AQAB</Exponent></RSAKeyValue>";
    }
}
